// Conservative per-new-group memory estimate. Covers map entry + bucket
// struct + key/keyCol allocations; calibrated against G7g bench (TBD).
const aggEntrySize int64 = 512

// BuildOperators translates the GroupBy + Agg slice of MeasureQueryOptions
// into a list of BreakerOperators that, chained after the scan source, form
// the vectorized aggregation pipeline.
//
// Routing rules:
//   - GroupBy + Agg both set → emit a single BatchAggregation. The operator's
//     own keyIndex map produces per-group buckets and folds the agg slot;
//     a separate BatchGroupBy would double the row materialization.
//   - Agg set without GroupBy → scalar reduce: a BatchAggregation with no
//     key columns. Every row maps to one group, so a single output row is
//     emitted carrying the first-seen projected tags plus the agg result,
//     matching the row path's aggAllIterator.
//   - GroupBy set without Agg → raw GroupBy: a first-seen-row-per-group
//     BatchGroupBy. The output preserves the input schema; one row per
//     group is emitted in group-insertion order, matching the row path's
//     groupIterator + processor.go's current[0] read.
//   - Neither set → empty operator list; caller emits raw rows.
//
// tracker is the per-pipeline MemoryTracker (G7a); it must be non-nil when
// any operator is emitted so per-group reservations route to the shared
// budget. batchSize controls the operator's output pagination.
//
// mode selects the BatchAggregation strategy when an agg operator is built
// (Agg set): AggModeAll for single-node final reduce; AggModeMap for the
// distributed Map phase (G9f.2) that emits typed-column partials. mode is
// ignored for the raw-GroupBy branch (BatchGroupBy doesn't carry partial
// state — first-seen-row per group is already the final shape).
// AggModeReduce is rejected here loudly; its operator is built by the
// liaison-side reduce plan (G9f.3), not via BuildOperators.
func BuildOperators(
	opts model.MeasureQueryOptions, schema *vectorized.BatchSchema,
	tracker *vectorized.MemoryTracker, batchSize int, mode AggMode,
) ([]vectorized.BreakerOperator, error) {
	hasGroupBy := opts.GroupBy != nil && opts.GroupBy.TagFamily != "" && len(opts.GroupBy.TagNames) > 0
	hasAgg := opts.Agg != nil

	if !hasGroupBy && !hasAgg {
		return nil, nil
	}
	if tracker == nil {
		return nil, fmt.Errorf("vectorized.measure: BuildOperators requires a non-nil shared MemoryTracker")
	}
	if batchSize <= 0 {
		return nil, fmt.Errorf("vectorized.measure: batchSize must be > 0, got %d", batchSize)
	}
	if mode == AggModeReduce {
		return nil, fmt.Errorf("vectorized.measure: BuildOperators does not build AggModeReduce — that operator is built by the liaison reduce plan (G9f.3)")
	}

	var keyIndices []int
	if hasGroupBy {
		var keyErr error
		keyIndices, keyErr = lookupGroupByKeyIndices(schema, opts.GroupBy)
		if keyErr != nil {
			return nil, keyErr
		}
	}

	if !hasAgg {
		// Raw GroupBy: emit the first-seen row of each group with the
		// input schema unchanged. entrySize accounts for the per-group
		// bucket; rowSize is zero because at most one row is retained.
		pool := vectorized.NewBatchPool(schema, batchSize)
		gb := NewBatchGroupByFirst(schema, keyIndices, pool, batchSize, tracker, aggEntrySize)
		return []vectorized.BreakerOperator{gb}, nil
	}

	inputIdx, inputErr := lookupAggInputColumnIndex(schema, opts.Agg)
	if inputErr != nil {
		return nil, inputErr
	}

	aggFn, fnErr := protoAggFuncToInternal(opts.Agg.Func)
	if fnErr != nil {
		return nil, fnErr
	}

	// The agg result column inherits the target's name — field or tag —
	// to match the row-path aggregator (aggGroupIterator.Current() in
	// pkg/query/logical/measure/measure_plan_aggregation.go). Row-path
	// fixtures expect a single output field named after the original
	// input (e.g. "value"), not an auto-derived "<field>_<func>" suffix
	// like "value_sum" — the suffix would break proto.Equal parity in the
	// integration suite. The aggregation function lives on the operator
	// spec, not in the column name.
	//
	// keyIndices is empty for scalar reduce (Agg without GroupBy):
	// BatchAggregation.computeKey then returns the same key for every
	// row, so all rows collapse into a single output row carrying the
	// first-seen projected tags plus the agg result — the columnar
	// equivalent of the row path's aggAllIterator.
	spec := AggSpec{
		Func:     aggFn,
		InputCol: inputIdx,
		Output:   aggTargetName(opts.Agg),
		HideTag:  opts.Agg.HideTag,
	}
	// COUNT_DISTINCT's map-phase precondition (design §7.4 "De-duplicating
	// the partials", part (a)). computeKey ignores shard id, and a node
	// holding more than one shard emits one merged partial per group,
	// labeled with whichever shard's row created it first — a hint, not
	// an identity. Under replication, staggered shard placement
	// (pkg/node/round_robin.go's roundRobinSelector) means no two nodes
	// hold the same shard set, so two nodes' partials for the same group
	// can collide on that incidental label. Depending on which of the
	// colliding partials markDedupSeen's (shardID, groupKey) check keeps
	// vs. drops, the result can either double-count (the survivor still
	// includes a shard the dropped one also counted) or undercount (the
	// dropped one carried a shard the survivor never had) — the design
	// doc's worked 4-node/replicas=1 example walks both outcomes from the
	// same topology. Forcing one group per (shard, GroupBy-key) makes the
	// emitted shard_id exact rather than incidental, so only a genuine
	// replica duplicate can ever share a dedup key.
	//
	// This same defect is latent in every distributed agg today, not only
	// COUNT_DISTINCT — design §7.4 tracks that as a parallel, non-gating
	// investigation (stage 4a) rather than fixing it here for every
	// function.
	if aggFn == AggCountDistinct && mode == AggModeMap {
		if shardIdx := findShardIDIndex(schema); shardIdx >= 0 {
			keyIndices = append(keyIndices, shardIdx)
		}
	}
	agg := NewBatchAggregation(schema, keyIndices, []AggSpec{spec},
		mode, batchSize, tracker, aggEntrySize)
	return []vectorized.BreakerOperator{agg}, nil
}

// aggTargetName returns the name the agg result column inherits (design
// §5.2): the tag name when Agg targets a tag, otherwise the field name.
func aggTargetName(agg *model.MeasureAgg) string {
	if agg.TagName != "" {
		return agg.TagName
	}
	return agg.FieldName
}

// BuildTimeBucketOperator builds the BatchTimeBucket operator for a
// time-bucketed GroupBy (design §7.2), wrapping upstream directly. Unlike
// BuildOperators, this does not return a BreakerOperator to be attached via
// PipelineBuilder.Break: BatchTimeBucket is a PullOperator that pulls from
// upstream lazily inside its own NextBatch, which is what makes its memory
// bound real (see BatchTimeBucket's doc). Callers wire it in via
// PipelineBuilder.Transform instead. Check opts.GroupBy.GetTimeBucket() != nil
// before calling this rather than BuildOperators.
//
// tagKeyIndices are the already resolved tag GroupBy keys (empty for a
// bucket-only GroupBy, i.e. no tag key at all). Agg is optional, exactly as
// for the non-bucketed case: when absent this is a bucketed raw GroupBy
// (first-seen row per (bucket, tags)), when present it is a bucketed
// aggregate — both shapes reuse the same BatchTimeBucket, since
// BatchAggregation with zero AggSpecs already produces the raw-GroupBy
// shape. (The analyzer currently rejects the no-Agg case for real requests
// — BatchAggregation's empty-AggSpec output layout drops every projected
// field, unlike BatchGroupByFirst's full-schema passthrough — but
// BuildTimeBucketOperator itself stays agnostic to that policy choice.)
func BuildTimeBucketOperator(
	upstream vectorized.PullOperator, opts model.MeasureQueryOptions, schema *vectorized.BatchSchema,
	tracker *vectorized.MemoryTracker, batchSize int, mode AggMode,
) (*BatchTimeBucket, error) {
	if tracker == nil {
		return nil, fmt.Errorf("vectorized.measure: BuildTimeBucketOperator requires a non-nil shared MemoryTracker")
	}
	if batchSize <= 0 {
		return nil, fmt.Errorf("vectorized.measure: batchSize must be > 0, got %d", batchSize)
	}
	if mode == AggModeReduce {
		return nil, fmt.Errorf("vectorized.measure: BuildTimeBucketOperator does not build AggModeReduce — that operator is built by the liaison reduce plan")
	}
	var tagKeyIndices []int
	if opts.GroupBy != nil && opts.GroupBy.TagFamily != "" && len(opts.GroupBy.TagNames) > 0 {
		var keyErr error
		tagKeyIndices, keyErr = lookupGroupByKeyIndices(schema, opts.GroupBy)
		if keyErr != nil {
			return nil, keyErr
		}
	}
	timestampIdx := schema.TimestampIndex()
	if timestampIdx < 0 {
		return nil, fmt.Errorf("vectorized.measure: time_bucket requires a RoleTimestamp column in the scan schema")
	}
	var specs []AggSpec
	var aggFn AggFunc
	if opts.Agg != nil {
		inputIdx, inputErr := lookupAggInputColumnIndex(schema, opts.Agg)
		if inputErr != nil {
			return nil, inputErr
		}
		var fnErr error
		aggFn, fnErr = protoAggFuncToInternal(opts.Agg.Func)
		if fnErr != nil {
			return nil, fnErr
		}
		specs = []AggSpec{{
			Func:     aggFn,
			InputCol: inputIdx,
			Output:   aggTargetName(opts.Agg),
			HideTag:  opts.Agg.HideTag,
		}}
	}
	// Same COUNT_DISTINCT map-phase precondition as BuildOperators (see its
	// comment for the full derivation): a data node's per-bucket aggregator
	// can still see rows from more than one of its local shards in a
	// single upstream batch, so the shard-id column must be part of the
	// group key — otherwise BatchTimeBucket would merge those shards into
	// one incidentally-labeled partial per bucket, exactly the shape the
	// fix in BuildOperators exists to prevent for the unbucketed case.
	if opts.Agg != nil && aggFn == AggCountDistinct && mode == AggModeMap {
		if shardIdx := findShardIDIndex(schema); shardIdx >= 0 {
			tagKeyIndices = append(tagKeyIndices, shardIdx)
		}
	}
	tb := opts.GroupBy.TimeBucket
	return NewBatchTimeBucket(upstream, schema, tagKeyIndices, timestampIdx, tb.WidthNanos,
		specs, mode, batchSize, tracker, aggEntrySize, !tb.UseIndexModeMap), nil
}

// lookupGroupByKeyIndices resolves each GroupBy tag name to its column index
// in schema. All names must exist within the configured tag family.
func lookupGroupByKeyIndices(schema *vectorized.BatchSchema, gb *model.MeasureGroupBy) ([]int, error) {
	indices := make([]int, 0, len(gb.TagNames))
	for _, name := range gb.TagNames {
		idx := -1
		for i, def := range schema.Columns {
			if def.Role == vectorized.RoleTag && def.TagFamily == gb.TagFamily && def.Name == name {
				idx = i
				break
			}
		}
		if idx < 0 {
			return nil, fmt.Errorf("vectorized.measure: GroupBy tag %s.%s not present in schema", gb.TagFamily, name)
		}
		indices = append(indices, idx)
	}
	return indices, nil
}

// lookupFieldColumnIndex resolves the agg input field name to its column
// index. Only field columns (Role == RoleField) are eligible.
func lookupFieldColumnIndex(schema *vectorized.BatchSchema, name string) (int, error) {
	for i, def := range schema.Columns {
		if def.Role == vectorized.RoleField && def.Name == name {
			return i, nil
		}
	}
	return -1, fmt.Errorf("vectorized.measure: Agg field %q not present in schema", name)
}

// lookupAggInputColumnIndex resolves agg's target column: a tag sibling of
// lookupGroupByKeyIndices when agg.TagName is set (matched on RoleTag +
// TagFamily + Name, which disambiguates a schema carrying the same tag name in
// two families; api/validate.UniqueTagNames rejects that shape on the
// registry's create and update paths only, so an older persisted schema can
// still carry it), otherwise the existing field lookup.
func lookupAggInputColumnIndex(schema *vectorized.BatchSchema, agg *model.MeasureAgg) (int, error) {
	if agg.TagName == "" {
		return lookupFieldColumnIndex(schema, agg.FieldName)
	}
	for i, def := range schema.Columns {
		if def.Role == vectorized.RoleTag && def.TagFamily == agg.TagFamily && def.Name == agg.TagName {
			return i, nil
		}
	}
	return -1, fmt.Errorf("vectorized.measure: Agg tag %s.%s not present in schema", agg.TagFamily, agg.TagName)
}

// protoAggFuncToInternal maps the proto AggregationFunction enum to the
// internal AggFunc constant. UNSPECIFIED is rejected — Aggregation must
// name a concrete function.
func protoAggFuncToInternal(f modelv1.AggregationFunction) (AggFunc, error) {
	switch f {
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_SUM:
		return AggSum, nil
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_COUNT:
		return AggCount, nil
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_MIN:
		return AggMin, nil
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_MAX:
		return AggMax, nil
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_MEAN:
		return AggMean, nil
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_UNSPECIFIED:
		return 0, fmt.Errorf("vectorized.measure: Agg.Function is UNSPECIFIED")
	case modelv1.AggregationFunction_AGGREGATION_FUNCTION_COUNT_DISTINCT:
		return AggCountDistinct, nil
	}
	return 0, fmt.Errorf("vectorized.measure: unknown AggregationFunction %v", f)
}

	if len(mqo.Entities) < 1 {
		return errors.New("invalid query options: series is required")
	}
	return nil
}

func applyMeasureQueryOrdering(mqo model.MeasureQueryOptions, result *queryResult) {
	if mqo.Order == nil {
		result.ascTS = true
		result.orderByTS = true
		return
	}
	if mqo.Order.Sort == modelv1.Sort_SORT_ASC || mqo.Order.Sort == modelv1.Sort_SORT_UNSPECIFIED {
		result.ascTS = true
	}
	result.orderByTS = mqo.Order.Type == index.OrderByTypeTime
}

func applyTopNOptions(mqo model.MeasureQueryOptions, result *queryResult) {
	if mqo.Name != TopNSchemaName {
		return
	}
	result.topNQueryOptions = &topNQueryOptions{
		sortDirection: mqo.Sort,
		number:        mqo.Number,
		fieldType:     mqo.TopNFieldType,
	}
}

type tagNameWithType struct {
	fieldName string
	typ       pbv1.ValueType
}

func (m *measure) searchSeriesList(ctx context.Context, series []*pbv1.Series, mqo model.MeasureQueryOptions,
	segments []storage.Segment[*tsTable, option],
) (sl []common.SeriesID, tables []*tsTable, tableShardIDs []common.ShardID, caches []storage.Cache, storedIndexValue map[common.SeriesID]map[string]*modelv1.TagValue,
	newTagProjection []model.TagProjection, err error,
) {
	var indexProjection []index.FieldKey
	fieldToValueType := make(map[string]tagNameWithType)
	var projectedEntityOffsets map[string]int
	newTagProjection = make([]model.TagProjection, 0)
	is := m.indexSchema.Load().(indexSchema)
	for _, tp := range mqo.TagProjection {
		var tagProjection model.TagProjection
	TAG:
		for _, n := range tp.Names {
			for i := range m.schema.GetEntity().GetTagNames() {
				if n == m.schema.GetEntity().GetTagNames()[i] {
					if projectedEntityOffsets == nil {
						projectedEntityOffsets = make(map[string]int)
					}
					projectedEntityOffsets[n] = i
					continue TAG
				}
			}
			if is.fieldIndexLocation != nil {
				if fields, ok := is.fieldIndexLocation[tp.Family]; ok {
					if field, ok := fields[n]; ok {
						indexProjection = append(indexProjection, field.Key)
						fieldToValueType[field.Key.Marshal()] = tagNameWithType{
							fieldName: n,
							typ:       field.Type,
						}
						continue TAG
					}
				}
			}
			tagProjection.Family = tp.Family
			tagProjection.Names = append(tagProjection.Names, n)
		}
		if tagProjection.Family != "" {
			newTagProjection = append(newTagProjection, tagProjection)
		}
	}

	// Collect all search results first
	var segResults []*segResult
	var needsSorting bool
	seriesFilter := roaring.NewPostingList()

	for i := range segments {
		sd, sortedValues, err := segments[i].IndexDB().Search(ctx, series, storage.IndexSearchOpts{
			Query:       mqo.Query,
			Order:       mqo.Order,
			PreloadSize: preloadSize,
			Projection:  indexProjection,
		})
		if err != nil {
			return nil, nil, nil, nil, nil, nil, err
		}
		if len(sd.SeriesList) > 0 {
			tt, shardIDs, cc := segments[i].TablesWithShardIDs()
			tables = append(tables, tt...)
			tableShardIDs = append(tableShardIDs, shardIDs...)
			caches = append(caches, cc...)

			// Create segResult for this segment
			sr := &segResult{
				SeriesData:   sd,
				sortedValues: sortedValues,
				i:            0,
			}
			segResults = append(segResults, sr)

			// Check if we need sorting
			if mqo.Order != nil && sortedValues != nil {
				needsSorting = true
			}
		}
	}

	// Sort if needed, otherwise use original order
	if needsSorting && len(segResults) > 0 {
		// Use segResultHeap to sort
		segHeap := &segResultHeap{
			results:  segResults,
			sortDesc: mqo.Order.Sort == modelv1.Sort_SORT_DESC,
		}
		heap.Init(segHeap)

		// Extract sorted series IDs
		for segHeap.Len() > 0 {
			top := heap.Pop(segHeap).(*segResult)
			series := top.SeriesList[top.i]

			if seriesFilter.Contains(uint64(series.ID)) {
				// Move to next in this segment
				top.i++
				if top.i < len(top.SeriesList) {
					heap.Push(segHeap, top)
				}
				continue
			}

			seriesFilter.Insert(uint64(series.ID))
			sl = append(sl, series.ID)

			// Build storedIndexValue for this series
			var fieldResult map[string][]byte
			if top.Fields != nil && top.i < len(top.Fields) {
				fieldResult = top.Fields[top.i]
			}
			storedIndexValue = m.buildStoredIndexValue(
				series.ID,
				series.EntityValues,
				fieldResult,
				projectedEntityOffsets,
				fieldToValueType,
				storedIndexValue,
			)

			// Move to next in this segment
			top.i++
			if top.i < len(top.SeriesList) {
				heap.Push(segHeap, top)
			}
		}
	} else {
		// Original logic when no sorting is needed
		for _, sr := range segResults {
			for j := range sr.SeriesList {
				if seriesFilter.Contains(uint64(sr.SeriesList[j].ID)) {
					continue
				}
				seriesFilter.Insert(uint64(sr.SeriesList[j].ID))
				sl = append(sl, sr.SeriesList[j].ID)

				var fieldResult map[string][]byte
				if sr.Fields != nil && j < len(sr.Fields) {
					fieldResult = sr.Fields[j]
				}
				storedIndexValue = m.buildStoredIndexValue(
					sr.SeriesList[j].ID,
					sr.SeriesList[j].EntityValues,
					fieldResult,
					projectedEntityOffsets,
					fieldToValueType,
					storedIndexValue,
				)
			}
		}
	}

	return sl, tables, tableShardIDs, caches, storedIndexValue, newTagProjection, nil
}

