	}
	if len(tag.Values) < n {
		return nil, fmt.Errorf("BuildMeasureBatchFromResult: tag %s.%s has %d values, expected %d",
			def.TagFamily, def.Name, len(tag.Values), n)
	}
	for k := range n {
		appendTagValueAsTyped(col, tag.Values[k])
	}
	return col, nil
}

